#include <fstream>
#include <iostream>
#include <sstream>
#include <string>

void StripBOM(std::string& content) {
  if (content.size() >= 3 && content[0] == '\xef' && content[1] == '\xbb' &&
      content[2] == '\xbf') {
    content.erase(0, 3);
  }
}

int main(int argc, char* argv[]) {
  if (argc != 5) {
    std::cerr
        << "Usage: " << argv[0]
        << " <input_ll_file> <output_header_file> <variable_name> <namespace>"
        << std::endl;
    return 1;
  }

  const std::string input_path = argv[1];
  const std::string output_path = argv[2];
  const std::string variable_name = argv[3];
  const std::string namespace_name = argv[4];

  std::ifstream input_file(input_path, std::ios::binary);
  if (!input_file) {
    std::cerr << "Error: Could not open input file " << input_path << std::endl;
    return 1;
  }

  std::stringstream buffer;
  buffer << input_file.rdbuf();
  std::string content = buffer.str();
  input_file.close();

  StripBOM(content);

  std::ofstream output_file(output_path);
  if (!output_file) {
    std::cerr << "Error: Could not open output file " << output_path
              << std::endl;
    return 1;
  }

  output_file << "#pragma once\n\n";
  output_file << "// This file is generated by the cc_to_llvm_ir_header rule. "
                 "Do not edit.\n\n";
  output_file << "namespace " << namespace_name << " {\n\n";
  output_file << "// LLVM IR compiled for the current architecture\n";
  output_file << "inline constexpr char " << variable_name << "[] = R\"IR(\n";
  output_file << content << "\n";
  output_file << ")IR\";\n\n";
  output_file << "}  // namespace " << namespace_name << "\n";

  output_file.close();
  return 0;
}
